contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // amount: Ether to first send into C via its fallback by calling c.fallback through a plain payable top-level call is not allowed,
    // so we instead rely on the public surface: we send Ether to C by calling its sendMoney to itself (which is allowed and state-changing)
    // valueToDeposit: amount of Ether to deposit into C before withdrawAll
    function run(uint valueToDeposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= valueToDeposit);

        // observe before-values
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // send Ether into c by having the owner (this contract) call sendMoney sending valueToDeposit to C itself
        // this is a top-level state-changing call on c
        c.sendMoney(address(c), valueToDeposit, ""); if (__ESBMC_reverted()) return;

        // read after-deposit values
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // now owner (this contract) calls withdrawAll() to withdraw entire balance
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        // observe final values
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // The general rule: withdrawAll, when called by the owner, empties the contract balance (finalBalance == 0)
        // and does not change depositsCount (it is only affected by fallback), and owner remains unchanged.
        assert(c.owner() == beforeOwner && finalBalance == 0 && finalDeposits == afterDeposits);
    }

    receive() external payable {}
}

