// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 valueToDeposit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= valueToDeposit);
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.sendMoney(address(c), valueToDeposit, "") {} catch { return; }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint finalBalance = address(c).balance;
        uint256 finalDeposits;
        try c.depositsCount() returns (uint256 __r) { finalDeposits = __r; } catch { return; }
        assertTrue(c.owner() == beforeOwner && finalBalance == 0 && finalDeposits == afterDeposits);
    }

    function testFuzz_run(uint256 valueToDeposit) public {
        _run(valueToDeposit);
    }

    receive() external payable {}
}
